import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { meApi } from '../api/me';
import { CustomerOrder, Pagination } from '../types';
import { useShop } from '../context/ShopContext';
import {
  Package,
  Calendar,
  CheckCircle2,
  Clock,
  ArrowRight,
  Loader2,
  RefreshCw,
  AlertCircle,
  Truck,
  RotateCcw,
} from 'lucide-react';

export const Orders: React.FC = () => {
  const { formatPrice } = useShop();
  const [orders, setOrders] = useState<CustomerOrder[]>([]);
  const [pagination, setPagination] = useState<Pagination>({
    page: 1,
    limit: 15,
    total: 0,
    totalPages: 1,
  });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchOrders = async (targetPage = 1) => {
    setLoading(true);
    setError(null);
    try {
      const res = await meApi.getOrders(targetPage, pagination.limit);
      setOrders(res.orders);
      setPagination(res.pagination);
    } catch (err: any) {
      setError(err?.error || err?.message || 'Could not load your orders.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchOrders(1);
  }, []);

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'PAID':
      case 'DELIVERED':
        return (
          <span className="px-2.5 py-0.5 rounded-full text-[10px] font-mono font-bold bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border border-emerald-500/20">
            {status}
          </span>
        );
      case 'SHIPPED':
      case 'PROCESSING':
        return (
          <span className="px-2.5 py-0.5 rounded-full text-[10px] font-mono font-bold bg-blue-500/10 text-blue-600 dark:text-blue-400 border border-blue-500/20">
            {status}
          </span>
        );
      case 'PARTIALLY_REFUNDED':
      case 'REFUNDED':
        return (
          <span className="px-2.5 py-0.5 rounded-full text-[10px] font-mono font-bold bg-purple-500/10 text-purple-600 dark:text-purple-400 border border-purple-500/20">
            {status}
          </span>
        );
      case 'CANCELLED':
      case 'FAILED':
        return (
          <span className="px-2.5 py-0.5 rounded-full text-[10px] font-mono font-bold bg-rose-500/10 text-rose-600 dark:text-rose-400 border border-rose-500/20">
            {status}
          </span>
        );
      default:
        return (
          <span className="px-2.5 py-0.5 rounded-full text-[10px] font-mono font-bold bg-amber-500/10 text-amber-600 dark:text-amber-400 border border-amber-500/20">
            {status}
          </span>
        );
    }
  };

  return (
    <div className="max-w-5xl mx-auto px-4 py-12">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-8 pb-6 border-b border-slate-200 dark:border-slate-800">
        <div>
          <h1 className="font-display text-2xl sm:text-3xl font-bold text-slate-900 dark:text-white">
            Order History
          </h1>
          <p className="text-xs sm:text-sm text-slate-500 dark:text-slate-400 mt-1">
            Authoritative records of all completed transactions and digital fulfillments.
          </p>
        </div>

        <div className="flex items-center gap-3">
          <Link
            to="/refunds"
            className="px-3.5 py-2 rounded-xl border border-slate-200 dark:border-slate-800 hover:bg-slate-100 dark:hover:bg-slate-900 text-xs font-semibold text-slate-700 dark:text-slate-300 inline-flex items-center gap-1.5 transition-colors"
          >
            <RotateCcw size={13} />
            <span>Refund History</span>
          </Link>
          <button
            type="button"
            onClick={() => fetchOrders(pagination.page)}
            disabled={loading}
            className="px-3.5 py-2 rounded-xl border border-slate-200 dark:border-slate-800 hover:bg-slate-100 dark:hover:bg-slate-900 text-xs font-semibold text-slate-700 dark:text-slate-300 inline-flex items-center gap-1.5 transition-colors"
          >
            <RefreshCw size={13} className={loading ? 'animate-spin' : ''} />
            <span>Refresh</span>
          </button>
        </div>
      </div>

      {loading ? (
        <div className="flex flex-col items-center justify-center py-20 text-slate-400">
          <Loader2 size={32} className="animate-spin text-emerald-500 mb-3" />
          <span className="text-xs font-mono">Loading orders from server...</span>
        </div>
      ) : error ? (
        <div className="p-8 rounded-2xl bg-rose-500/10 border border-rose-500/20 text-center max-w-md mx-auto">
          <AlertCircle size={28} className="text-rose-500 mx-auto mb-3" />
          <h2 className="font-display text-base font-bold text-slate-900 dark:text-white mb-1">
            Could Not Load Orders
          </h2>
          <p className="text-xs text-slate-500 dark:text-slate-400 mb-4">{error}</p>
          <button
            type="button"
            onClick={() => fetchOrders(1)}
            className="px-4 py-2 bg-emerald-600 text-white rounded-lg text-xs font-semibold"
          >
            Retry
          </button>
        </div>
      ) : orders.length === 0 ? (
        <div className="p-12 rounded-2xl bg-white dark:bg-[#101216] border border-slate-200 dark:border-slate-800 text-center max-w-md mx-auto">
          <div className="w-14 h-14 rounded-2xl bg-slate-100 dark:bg-slate-800 flex items-center justify-center text-slate-400 mx-auto mb-4">
            <Package size={26} />
          </div>
          <h2 className="font-display text-lg font-bold text-slate-900 dark:text-white mb-2">
            No Orders Placed Yet
          </h2>
          <p className="text-xs text-slate-500 dark:text-slate-400 mb-6">
            When you complete checkout via ZarinPal, your orders and receipts will appear here.
          </p>
          <Link
            to="/shop"
            className="inline-flex items-center gap-2 px-5 py-2.5 bg-emerald-600 hover:bg-emerald-500 text-white rounded-xl text-xs font-semibold"
          >
            <span>Explore Catalog</span>
          </Link>
        </div>
      ) : (
        <div className="space-y-4">
          {orders.map(order => (
            <div
              key={order.orderId}
              className="p-6 rounded-2xl bg-white dark:bg-[#101216] border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col md:flex-row md:items-center justify-between gap-6"
            >
              <div className="space-y-2">
                <div className="flex flex-wrap items-center gap-2.5">
                  <span className="font-mono text-xs font-bold text-slate-900 dark:text-white">
                    #{order.orderId}
                  </span>
                  {getStatusBadge(order.status)}
                  {order.fulfillmentStatus && (
                    <span className="text-[10px] font-mono text-slate-500 dark:text-slate-400">
                      Fulfillment: {order.fulfillmentStatus}
                    </span>
                  )}
                </div>

                <div className="text-xs text-slate-500 dark:text-slate-400 font-mono flex flex-wrap items-center gap-4">
                  <span className="flex items-center gap-1">
                    <Calendar size={12} />
                    <span>{new Date(order.createdAt).toLocaleDateString()}</span>
                  </span>
                  <span>
                    {order.items?.length || 0} line item{(order.items?.length || 0) === 1 ? '' : 's'}
                  </span>
                  {order.shipping?.trackingNumber && (
                    <span className="flex items-center gap-1 text-emerald-600 dark:text-emerald-400">
                      <Truck size={12} />
                      <span>Tracking: {order.shipping.trackingNumber}</span>
                    </span>
                  )}
                </div>

                {order.items && order.items.length > 0 && (
                  <div className="text-xs text-slate-700 dark:text-slate-300 truncate max-w-lg">
                    {order.items.map(i => i.name).join(', ')}
                  </div>
                )}
              </div>

              <div className="flex items-center justify-between md:justify-end gap-6 pt-4 md:pt-0 border-t md:border-t-0 border-slate-100 dark:border-slate-800">
                <div className="text-left md:text-right">
                  <div className="text-[10px] uppercase font-mono tracking-wider text-slate-400">
                    Total Amount
                  </div>
                  <div className="font-mono text-base font-bold text-slate-900 dark:text-white">
                    {formatPrice(order.totalAmount, order.currency)}
                  </div>
                </div>

                <Link
                  to={`/orders/${order.orderId}`}
                  className="px-4 py-2.5 rounded-xl bg-slate-100 hover:bg-slate-200 dark:bg-slate-800 dark:hover:bg-slate-700 text-xs font-semibold text-slate-900 dark:text-white inline-flex items-center gap-1.5 transition-colors"
                >
                  <span>Details</span>
                  <ArrowRight size={13} />
                </Link>
              </div>
            </div>
          ))}

          {/* Pagination controls */}
          {pagination.totalPages > 1 && (
            <div className="flex items-center justify-center gap-2 pt-6">
              <button
                type="button"
                disabled={pagination.page <= 1}
                onClick={() => fetchOrders(pagination.page - 1)}
                className="px-3 py-1.5 rounded-lg border border-slate-200 dark:border-slate-800 text-xs font-semibold disabled:opacity-30"
              >
                Previous
              </button>
              <span className="text-xs font-mono text-slate-500 px-3">
                Page {pagination.page} of {pagination.totalPages}
              </span>
              <button
                type="button"
                disabled={pagination.page >= pagination.totalPages}
                onClick={() => fetchOrders(pagination.page + 1)}
                className="px-3 py-1.5 rounded-lg border border-slate-200 dark:border-slate-800 text-xs font-semibold disabled:opacity-30"
              >
                Next
              </button>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default Orders;
